#import <AppKit/AppKit.h>
#import "SINSliceExport.h"
static NSUInteger checks;
static void Check(BOOL ok,NSString *message){checks++;if(!ok){fprintf(stderr,"FAIL: %s\n",message.UTF8String);exit(1);}}
static NSError *Write(SINSliceExport *owner,NSString *token,NSUInteger index,NSString *url){__block BOOL done=NO;__block NSError *error;[owner writeToken:token index:index dataURL:url completion:^(NSError *e){error=e;done=YES;}];NSDate *limit=[NSDate dateWithTimeIntervalSinceNow:10];while(!done&&limit.timeIntervalSinceNow>0)[NSRunLoop.currentRunLoop runUntilDate:[NSDate dateWithTimeIntervalSinceNow:.01]];Check(done,@"slice write completes");return error;}
int main(void){@autoreleasepool{
    NSFileManager *fm=NSFileManager.defaultManager;NSString *root=[NSTemporaryDirectory() stringByAppendingPathComponent:[@"Sin-slices-" stringByAppendingString:NSUUID.UUID.UUIDString]];[fm createDirectoryAtPath:root withIntermediateDirectories:YES attributes:nil error:nil];
    NSBitmapImageRep *bitmap=[[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:2 pixelsHigh:3 bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO colorSpaceName:NSDeviceRGBColorSpace bytesPerRow:8 bitsPerPixel:32];memset(bitmap.bitmapData,127,24);NSData *png=[bitmap representationUsingType:NSBitmapImageFileTypePNG properties:@{}];NSString *url=[@"data:image/png;base64," stringByAppendingString:[png base64EncodedStringWithOptions:0]];
    SINSliceExport *owner=SINSliceExport.new;NSError *error=nil;Check(![owner beginInDirectory:root name:@"Image" count:0 error:&error]&&error,@"reject zero cells");
    NSString *token=[owner beginInDirectory:root name:@"../Test:Image" count:2 error:&error];Check(token.length>0,@"begin native export");Check(![owner beginInDirectory:root name:@"Other" count:1 error:&error],@"reject overlapping exports");
    Check(Write(owner,@"wrong",0,url)!=nil,@"reject stale tokens");Check(Write(owner,token,1,url)!=nil,@"enforce sequential cells");Check(Write(owner,token,0,@"data:image/png;base64,AA==")!=nil,@"reject malformed PNG");
    Check(!Write(owner,token,0,url),@"write first PNG");Check(Write(owner,token,0,url)!=nil,@"reject duplicate cell");
    NSDictionary *result=[owner endToken:token error:&error];Check([result[@"saved"] integerValue]==1&&[result[@"total"] integerValue]==2,@"cancel retains completed cells and reports progress");
    NSString *folder=result[@"folder"];Check([folder.stringByDeletingLastPathComponent isEqual:root],@"untrusted image name cannot escape chosen parent");NSArray *files=[fm contentsOfDirectoryAtPath:folder error:nil];Check(files.count==1&&[files[0] hasSuffix:@"Cell 01.png"],@"sequential cell naming excludes temporary files");Check([[NSData dataWithContentsOfFile:[folder stringByAppendingPathComponent:files[0]]] isEqual:png],@"slice PNG bytes are preserved");
    Check(![owner endToken:token error:&error],@"ended token cannot be reused");NSString *next=[owner beginInDirectory:root name:@"../Test:Image" count:1 error:&error];Check(next.length&&!Write(owner,next,0,url),@"next export succeeds without overwriting previous export");NSDictionary *second=[owner endToken:next error:&error];Check(![second[@"folder"] isEqual:folder],@"repeated export reserves a fresh folder");
    token=[owner beginInDirectory:root name:@"Collision" count:1 error:&error];NSString *collision=[root stringByAppendingPathComponent:@"Collision - Slices/Collision - Cell 01.png"];NSData *sentinel=[@"external edit" dataUsingEncoding:NSUTF8StringEncoding];[sentinel writeToFile:collision atomically:YES];Check(Write(owner,token,0,url)!=nil,@"publication refuses concurrent destination file");Check([[NSData dataWithContentsOfFile:collision] isEqual:sentinel],@"concurrent destination is preserved");result=[owner endToken:token error:&error];Check([result[@"saved"] integerValue]==0,@"failed export reports no saved cells");
    [fm removeItemAtPath:root error:nil];printf("PASS: %lu slice export assertions\n",(unsigned long)checks);
}return 0;}
